from abc import ABC, abstractmethod

class WidgetFactory(ABC):
    @abstractmethod
    def create_button(self, label: str) -> Button: ...
    @abstractmethod
    def create_slider(self, lo: int, hi: int) -> Slider: ...

class DarkTheme(WidgetFactory):
    def create_button(self, label: str) -> Button: return DarkButton(label)
    def create_slider(self, lo: int, hi: int) -> Slider: return DarkSlider(lo, hi)
